import { defineProjector } from '../domain/projections/projection-runner.mjs';
import { HANDOFF_PROPOSAL_STATUS, normalizeHandoffMetadata } from './proposal.mjs';

export const HANDOFF_PROJECTOR_ID = 'tmrw-main-rp-handoff-v1';
const lineageKey = handoff => `${handoff.sourceAuthority}:${handoff.sourceMessageId}:${handoff.actionKey}`;
const linkId = (scope, handoff) => `handoff-link:${scope.storyId}:${scope.branchId}:${lineageKey(handoff)}`;
const cursorId = (scope, authority) => `handoff-cursor:${scope.storyId}:${scope.branchId}:${authority}`;
function project(event) { const input = event.payload?.handoff; if (!input) return []; const handoff = normalizeHandoffMetadata(input); return [{ kind: 'main-rp-handoff-link', projectionKey: lineageKey(handoff), groupKey: lineageKey(handoff), data: { handoff, canonicalEventId: event.id, canonicalEventType: event.eventType } }]; }
async function materialize(repositories, scope, groupKey, rows, previousRows, updatedAt) {
  const current = [...rows].sort((a, b) => a.sourceEventSequence - b.sourceEventSequence).at(-1); const prior = previousRows.at(-1); const data = current?.data || prior?.data; if (!data) return { rowsWritten: 0 };
  const id = linkId(scope, data.handoff); const proposal = await repositories.handoffProposals.get(data.handoff.proposalId);
  if (!current) { await repositories.handoffLinks.delete(id); if (proposal) await repositories.handoffProposals.put(Object.freeze({ ...proposal, status: HANDOFF_PROPOSAL_STATUS.RETRACTED, canonicalEventId: data.canonicalEventId, canonicalEventRevision: prior?.sourceEventRevision || proposal.canonicalEventRevision, updatedAt })); return { rowsWritten: proposal ? 1 : 0 }; }
  await repositories.handoffLinks.put(Object.freeze({ id, storyId: scope.storyId, branchId: scope.branchId, ...data.handoff, canonicalEventId: data.canonicalEventId, canonicalEventType: data.canonicalEventType, canonicalEventRevision: current.sourceEventRevision, sourceEventSequence: current.sourceEventSequence, updatedAt, phase: 10 }));
  if (proposal) await repositories.handoffProposals.put(Object.freeze({ ...proposal, sourceVersionId: data.handoff.sourceVersionId, sourceOrdinal: data.handoff.sourceOrdinal, sourceContentDigest: data.handoff.sourceContentDigest, status: HANDOFF_PROPOSAL_STATUS.ACCEPTED, canonicalEventId: data.canonicalEventId, canonicalEventRevision: current.sourceEventRevision, updatedAt }));
  const cursorKey = cursorId(scope, data.handoff.sourceAuthority); const cursor = await repositories.handoffSourceCursors.get(cursorKey); if (!cursor || data.handoff.sourceOrdinal >= cursor.lastAcceptedSourceOrdinal) await repositories.handoffSourceCursors.put(Object.freeze({ id: cursorKey, storyId: scope.storyId, branchId: scope.branchId, sourceAuthority: data.handoff.sourceAuthority, lastAcceptedSourceOrdinal: data.handoff.sourceOrdinal, lastAcceptedSourceMessageId: data.handoff.sourceMessageId, lastAcceptedSourceVersionId: data.handoff.sourceVersionId, lastCanonicalEventId: data.canonicalEventId, updatedAt, phase: 10, historicalBootstrap: false }));
  return { rowsWritten: 2 + (proposal ? 1 : 0) };
}
async function rowsForGroup(repositories, scope, groupKey) { return repositories.projections.listByIndex('by_scope_kind_key', [scope.storyId, scope.branchId, 'main-rp-handoff-link', groupKey]); }
async function applyAggregate({ repositories, scope, previousRows, currentRows, updatedAt }) { let rowsWritten = 0; for (const key of new Set([...previousRows, ...currentRows].map(row => row.groupKey).filter(Boolean))) { const rows = await rowsForGroup(repositories, scope, key); rowsWritten += (await materialize(repositories, scope, key, rows, previousRows.filter(row => row.groupKey === key), updatedAt)).rowsWritten; } return { sourceRowsRead: currentRows.length, rowsWritten, eventHistoryScans: 0 }; }
async function rebuildAggregate({ repositories, scope, updatedAt }) { for (const row of await repositories.handoffLinks.list()) await repositories.handoffLinks.delete(row.id); for (const row of await repositories.handoffSourceCursors.list()) await repositories.handoffSourceCursors.delete(row.id); for (const proposal of await repositories.handoffProposals.list()) if (proposal.status === HANDOFF_PROPOSAL_STATUS.ACCEPTED) await repositories.handoffProposals.put(Object.freeze({ ...proposal, status: HANDOFF_PROPOSAL_STATUS.READY, canonicalEventId: null, canonicalEventRevision: null, updatedAt })); const rows = await repositories.projections.listByIndex('by_scope_projector', [scope.storyId, scope.branchId, HANDOFF_PROJECTOR_ID]); let written = 0; for (const key of new Set(rows.map(row => row.groupKey))) written += (await materialize(repositories, scope, key, rows.filter(row => row.groupKey === key), [], updatedAt)).rowsWritten; const retracted = (await repositories.events.list()).filter(event => event.status === 'retracted' && event.payload?.handoff); for (const event of retracted) { const proposal = await repositories.handoffProposals.get(event.payload.handoff.proposalId); if (proposal) { await repositories.handoffProposals.put(Object.freeze({ ...proposal, status: HANDOFF_PROPOSAL_STATUS.RETRACTED, canonicalEventId: event.id, canonicalEventRevision: event.revision, updatedAt })); written += 1; } } return { sourceRowsRead: rows.length + retracted.length, rowsWritten: written }; }
export function createHandoffProjector() { return defineProjector({ id: HANDOFF_PROJECTOR_ID, version: 1, stores: ['handoffProposals', 'handoffLinks', 'handoffSourceCursors'], project, applyAggregate, rebuildAggregate }); }
